"""Sortie ZF4, batch 4: the vanishing of the Gauss sum of a primitive
character at a non-unit shift (Mathlib
gaussSum_eq_zero_of_isPrimitive_of_not_isPrimitive) and the shift identity
for every shift (gaussSum_mulShift_of_isPrimitive)."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
from zf4lib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

RN = R('N'); F0 = FZO('N'); L = LZ('N'); C = COND('N', 'X')
def XL(a): return EV('X', 'N', a)

# ---- dvdsmul12
A0 = '( ( K e. ZZ /\\ L e. ZZ ) /\\ ( M e. ZZ /\\ N e. ZZ ) /\\ ( K || M /\\ L || N ) )'
w = W('dvdsmul12', 'Divisibility of a product by a product of divisors.')
k = w.s([w.s([], 'simp1', '( %s -> ( K e. ZZ /\\ L e. ZZ ) )' % A0)], 'simpld', '( %s -> K e. ZZ )' % A0); l = w.s([w.s([], 'simp1', '( %s -> ( K e. ZZ /\\ L e. ZZ ) )' % A0)], 'simprd', '( %s -> L e. ZZ )' % A0)
m = w.s([w.s([], 'simp2', '( %s -> ( M e. ZZ /\\ N e. ZZ ) )' % A0)], 'simpld', '( %s -> M e. ZZ )' % A0); n = w.s([w.s([], 'simp2', '( %s -> ( M e. ZZ /\\ N e. ZZ ) )' % A0)], 'simprd', '( %s -> N e. ZZ )' % A0)
km = w.s([w.s([], 'simp3', '( %s -> ( K || M /\\ L || N ) )' % A0)], 'simpld', '( %s -> K || M )' % A0); ln = w.s([w.s([], 'simp3', '( %s -> ( K || M /\\ L || N ) )' % A0)], 'simprd', '( %s -> L || N )' % A0)
d1 = w.s([km, w.s([k, m, l, w.inst('dvdsmulc')], 'syl3anc', '( %s -> ( K || M -> ( K x. L ) || ( M x. L ) ) )' % A0)], 'mpd', '( %s -> ( K x. L ) || ( M x. L ) )' % A0)
d2 = w.s([ln, w.s([l, n, m, w.inst('dvdscmul')], 'syl3anc', '( %s -> ( L || N -> ( M x. L ) || ( M x. N ) ) )' % A0)], 'mpd', '( %s -> ( M x. L ) || ( M x. N ) )' % A0)
w.qed([w.s([d1, d2], 'jca', '( %s -> ( ( K x. L ) || ( M x. L ) /\\ ( M x. L ) || ( M x. N ) ) )' % A0), w.s([w.s([k, l], 'zmulcld', '( %s -> ( K x. L ) e. ZZ )' % A0), w.s([m, l], 'zmulcld', '( %s -> ( M x. L ) e. ZZ )' % A0), w.s([m, n], 'zmulcld', '( %s -> ( M x. N ) e. ZZ )' % A0), w.inst('dvdstr')], 'syl3anc', '( %s -> ( ( ( K x. L ) || ( M x. L ) /\\ ( M x. L ) || ( M x. N ) ) -> ( K x. L ) || ( M x. N ) ) )' % A0)], 'mpd', '( %s -> ( K x. L ) || ( M x. N ) )' % A0); run(w)

# ---- dvdsinvcop
A0 = '( Q e. NN /\\ ( A e. ZZ /\\ B e. ZZ ) /\\ Q || ( ( A x. B ) - 1 ) )'
GG = '( B gcd Q )'
w = W('dvdsinvcop', 'An integer with an inverse mod Q is coprime to Q.')
q = w.s([], 'simp1', '( %s -> Q e. NN )' % A0); a = w.s([w.s([], 'simp2', '( %s -> ( A e. ZZ /\\ B e. ZZ ) )' % A0)], 'simpld', '( %s -> A e. ZZ )' % A0); b = w.s([w.s([], 'simp2', '( %s -> ( A e. ZZ /\\ B e. ZZ ) )' % A0)], 'simprd', '( %s -> B e. ZZ )' % A0); dv = w.s([], 'simp3', '( %s -> Q || ( ( A x. B ) - 1 ) )' % A0)
qz = w.s([q], 'nnzd', '( %s -> Q e. ZZ )' % A0)
g0 = w.s([b, qz, w.inst('gcdcl')], 'syl2anc', '( %s -> %s e. NN0 )' % (A0, GG)); gz = w.s([g0], 'nn0zd', '( %s -> %s e. ZZ )' % (A0, GG))
gd = w.s([b, qz, w.inst('gcddvds')], 'syl2anc', '( %s -> ( %s || B /\\ %s || Q ) )' % (A0, GG, GG))
gb = w.s([gd], 'simpld', '( %s -> %s || B )' % (A0, GG)); gq = w.s([gd], 'simprd', '( %s -> %s || Q )' % (A0, GG))
ab = w.s([a, b], 'zmulcld', '( %s -> ( A x. B ) e. ZZ )' % A0); ab1 = w.s([ab, w.s([], '1zzd', '( %s -> 1 e. ZZ )' % A0)], 'zsubcld', '( %s -> ( ( A x. B ) - 1 ) e. ZZ )' % A0)
gab = w.s([gb, w.s([gz, a, b, w.inst('dvdsmultr2')], 'syl3anc', '( %s -> ( %s || B -> %s || ( A x. B ) ) )' % (A0, GG, GG))], 'mpd', '( %s -> %s || ( A x. B ) )' % (A0, GG))
gab1 = w.s([w.s([gq, dv], 'jca', '( %s -> ( %s || Q /\\ Q || ( ( A x. B ) - 1 ) ) )' % (A0, GG)), w.s([gz, qz, ab1, w.inst('dvdstr')], 'syl3anc', '( %s -> ( ( %s || Q /\\ Q || ( ( A x. B ) - 1 ) ) -> %s || ( ( A x. B ) - 1 ) ) )' % (A0, GG, GG))], 'mpd', '( %s -> %s || ( ( A x. B ) - 1 ) )' % (A0, GG))
s2 = w.s([w.s([gz, ab, w.s([], '1zzd', '( %s -> 1 e. ZZ )' % A0)], '3jca', '( %s -> ( %s e. ZZ /\\ ( A x. B ) e. ZZ /\\ 1 e. ZZ ) )' % (A0, GG)), gab1, w.inst('dvdssub2')], 'syl2anc', '( %s -> ( %s || ( A x. B ) <-> %s || 1 ) )' % (A0, GG, GG))
g1 = w.s([gab, s2], 'mpbid', '( %s -> %s || 1 )' % (A0, GG))
w.qed([g1, w.s([g0, w.inst('dvds1')], 'syl', '( %s -> ( %s || 1 <-> %s = 1 ) )' % (A0, GG, GG))], 'mpbid', '( %s -> %s = 1 )' % (A0, GG)); run(w)

# ---- dchrgs0lem1
A0 = '( N e. NN /\\ A e. ZZ /\\ -. %s )' % COP('A', 'N')
D = '( A gcd N )'; M = '( N / %s )' % D
w = W('dchrgs0lem1', 'Lemma for dchrgs0: for A not coprime to N, the quotient of N by the gcd is a proper divisor of N.')
n = w.s([], 'simp1', '( %s -> N e. NN )' % A0); a = w.s([], 'simp2', '( %s -> A e. ZZ )' % A0); nc = w.s([], 'simp3', '( %s -> -. %s )' % (A0, COP('A', 'N')))
nz = w.s([n], 'nnzd', '( %s -> N e. ZZ )' % A0)
d0 = w.s([a, nz, w.inst('gcdcl')], 'syl2anc', '( %s -> %s e. NN0 )' % (A0, D))
nn0 = w.s([w.s([n], 'nnne0d', '( %s -> N =/= 0 )' % A0)], 'neneqd', '( %s -> -. N = 0 )' % A0)
nand = w.s([nn0], 'intnand', '( %s -> -. ( A = 0 /\\ N = 0 ) )' % A0)
dne = w.s([w.s([nand, w.s([a, nz, w.inst('gcdeq0')], 'syl2anc', '( %s -> ( %s = 0 <-> ( A = 0 /\\ N = 0 ) ) )' % (A0, D))], 'mtbird', '( %s -> -. %s = 0 )' % (A0, D))], 'neqned', '( %s -> %s =/= 0 )' % (A0, D))
dn = w.s([w.s([d0, dne], 'jca', '( %s -> ( %s e. NN0 /\\ %s =/= 0 ) )' % (A0, D, D)), w.inst('elnnne0')], 'sylibr', '( %s -> %s e. NN )' % (A0, D))
gd = w.s([a, nz, w.inst('gcddvds')], 'syl2anc', '( %s -> ( %s || A /\\ %s || N ) )' % (A0, D, D))
da = w.s([gd], 'simpld', '( %s -> %s || A )' % (A0, D)); dnn = w.s([gd], 'simprd', '( %s -> %s || N )' % (A0, D))
mn = w.s([dnn, w.s([n, dn, w.inst('nndivdvds')], 'syl2anc', '( %s -> ( %s || N <-> %s e. NN ) )' % (A0, D, M))], 'mpbid', '( %s -> %s e. NN )' % (A0, M))
dm = w.s([w.s([n], 'nncnd', '( %s -> N e. CC )' % A0), w.s([dn], 'nncnd', '( %s -> %s e. CC )' % (A0, D)), dne, w.inst('divcan2')], 'syl3anc', '( %s -> ( %s x. %s ) = N )' % (A0, D, M))
mdn = w.s([w.s([w.s([dn], 'nnzd', '( %s -> %s e. ZZ )' % (A0, D)), w.s([mn], 'nnzd', '( %s -> %s e. ZZ )' % (A0, M)), w.inst('dvdsmul2')], 'syl2anc', '( %s -> %s || ( %s x. %s ) )' % (A0, M, D, M)), dm], 'breqtrd', '( %s -> %s || N )' % (A0, M))
# M < N
nr = w.s([n], 'nnred', '( %s -> N e. RR )' % A0); dr = w.s([dn], 'nnred', '( %s -> %s e. RR )' % (A0, D)); dgt = w.s([dn], 'nngt0d', '( %s -> 0 < %s )' % (A0, D))
lt1 = w.s([nr, nr, w.s([dr, dgt], 'jca', '( %s -> ( %s e. RR /\\ 0 < %s ) )' % (A0, D, D)), w.inst('ltdivmul')], 'syl3anc', '( %s -> ( %s < N <-> N < ( %s x. N ) ) )' % (A0, M, D))
lt2 = w.s([nr, dr, w.s([n], 'nngt0d', '( %s -> 0 < N )' % A0), w.inst('ltmulgt11')], 'syl3anc', '( %s -> ( 1 < %s <-> N < ( N x. %s ) ) )' % (A0, D, D))
d1 = w.s([nc, w.s([dn, w.inst('nngt1ne1')], 'syl', '( %s -> ( 1 < %s <-> %s =/= 1 ) )' % (A0, D, D))], 'mpbird' if False else 'mpbird', '( %s -> 1 < %s )' % (A0, D))
w.lines.pop()
d1 = w.s([w.s([nc], 'neqned', '( %s -> %s =/= 1 )' % (A0, D)), w.s([dn, w.inst('nngt1ne1')], 'syl', '( %s -> ( 1 < %s <-> %s =/= 1 ) )' % (A0, D, D))], 'mpbird', '( %s -> 1 < %s )' % (A0, D))
nlt = w.s([d1, lt2], 'mpbid', '( %s -> N < ( N x. %s ) )' % (A0, D))
cm = w.s([w.s([n], 'nncnd', '( %s -> N e. CC )' % A0), w.s([dn], 'nncnd', '( %s -> %s e. CC )' % (A0, D))], 'mulcomd', '( %s -> ( N x. %s ) = ( %s x. N ) )' % (A0, D, D))
nlt2 = w.s([nlt, cm], 'breqtrd', '( %s -> N < ( %s x. N ) )' % (A0, D))
mlt = w.s([nlt2, lt1], 'mpbird', '( %s -> %s < N )' % (A0, M))
w.qed([w.s([dn, da, dnn], '3jca', '( %s -> ( %s e. NN /\\ %s || A /\\ %s || N ) )' % (A0, D, D, D)), w.s([mn, mdn, mlt], '3jca', '( %s -> ( %s e. NN /\\ %s || N /\\ %s < N ) )' % (A0, M, M, M))], 'jca', '( %s -> ( ( %s e. NN /\\ %s || A /\\ %s || N ) /\\ ( %s e. NN /\\ %s || N /\\ %s < N ) ) )' % (A0, D, D, D, M, M, M)); run(w)

# ---- dchrgs0lem2: non-periodicity from primitivity
from zf2lib import PER, CSET
CS = CSET('N', 'X')
HP = '( %s /\\ %s = N )' % (HC, C)
A0 = '( %s /\\ ( M e. NN /\\ M || N /\\ M < N ) )' % HP
def P(s, t): return '( ( %s /\\ %s ) /\\ M || ( %s - %s ) )' % (COP(s, 'N'), COP(t, 'N'), s, t)
def Q(s, t): return '%s = %s' % (XL(s), XL(t))
def IMP(s, t): return '( %s -> %s )' % (P(s, t), Q(s, t))
def NEG(s, t): return '( %s /\\ -. %s )' % (P(s, t), Q(s, t))
PERM = PER('M')
assert PERM == 'A. a e. ZZ A. b e. ZZ %s' % IMP('a', 'b'), PERM
EX = 'E. s e. ZZ E. t e. ZZ %s' % NEG('s', 't')
w = W('dchrgs0lem2', 'Lemma for dchrgs0: a primitive character mod N is not periodic mod a proper divisor M on the units: there are units s, t congruent mod M with different values (from dchrcondmem and dchrcondper2).')
hp = w.s([], 'simpl', '( %s -> %s )' % (A0, HP)); hc = w.s([hp], 'simpld', '( %s -> %s )' % (A0, HC)); cn = w.s([hp], 'simprd', '( %s -> %s = N )' % (A0, C))
n = w.s([hc], 'simpld', '( %s -> N e. NN )' % A0)
mm = w.s([], 'simpr', '( %s -> ( M e. NN /\\ M || N /\\ M < N ) )' % A0); m = w.s([mm], 'simp1d', '( %s -> M e. NN )' % A0); md = w.s([mm], 'simp2d', '( %s -> M || N )' % A0); ml = w.s([mm], 'simp3d', '( %s -> M < N )' % A0)
mem = w.s([hc, w.s([m, md], 'jca', '( %s -> ( M e. NN /\\ M || N ) )' % A0), w.inst('dchrcondmem')], 'syl2anc', '( %s -> ( M e. %s <-> %s || M ) )' % (A0, CS, C))
mem2 = w.s([mem, w.s([cn], 'breq1d', '( %s -> ( %s || M <-> N || M ) )' % (A0, C))], 'bitrd', '( %s -> ( M e. %s <-> N || M ) )' % (A0, CS))
nle = w.s([w.s([m], 'nnred', '( %s -> M e. RR )' % A0), w.s([n], 'nnred', '( %s -> N e. RR )' % A0), w.inst('ltnled')], 'syl2anc', '( %s -> ( M < N <-> -. N <_ M ) )' % A0)
nle2 = w.s([ml, nle], 'mpbid', '( %s -> -. N <_ M )' % A0)
ndv = w.s([nle2, w.s([w.s([n], 'nnzd', '( %s -> N e. ZZ )' % A0), m, w.inst('dvdsle')], 'syl2anc', '( %s -> ( N || M -> N <_ M ) )' % A0)], 'mtod', '( %s -> -. N || M )' % A0)
nmem = w.s([ndv, mem2], 'mtbird', '( %s -> -. M e. %s )' % (A0, CS))
per = w.s([], 'dchrcondper2', '( ( ( %s /\\ %s ) /\\ ( M e. NN /\\ M || N ) ) -> M e. %s )' % (HC, PERM, CS))
per2 = w.s([w.s([per], 'an32s', '( ( ( %s /\\ ( M e. NN /\\ M || N ) ) /\\ %s ) -> M e. %s )' % (HC, PERM, CS))], 'ex', '( ( %s /\\ ( M e. NN /\\ M || N ) ) -> ( %s -> M e. %s ) )' % (HC, PERM, CS))
per3 = w.s([w.s([hc, w.s([m, md], 'jca', '( %s -> ( M e. NN /\\ M || N ) )' % A0)], 'jca', '( %s -> ( %s /\\ ( M e. NN /\\ M || N ) ) )' % (A0, HC)), per2], 'syl', '( %s -> ( %s -> M e. %s ) )' % (A0, PERM, CS))
nper = w.s([nmem, per3], 'mtod', '( %s -> -. %s )' % (A0, PERM))
# -. A. a A. b ( P -> Q ) <-> E. a E. b ( P /\ -. Q )
b1 = w.s([w.s([], 'rexnal', '( E. a e. ZZ -. A. b e. ZZ %s <-> -. %s )' % (IMP('a', 'b'), PERM))], 'bicomi', '( -. %s <-> E. a e. ZZ -. A. b e. ZZ %s )' % (PERM, IMP('a', 'b')))
b2 = w.s([w.s([], 'rexnal', '( E. b e. ZZ -. %s <-> -. A. b e. ZZ %s )' % (IMP('a', 'b'), IMP('a', 'b')))], 'bicomi', '( -. A. b e. ZZ %s <-> E. b e. ZZ -. %s )' % (IMP('a', 'b'), IMP('a', 'b')))
b3 = w.s([w.s([], 'annim', '( %s <-> -. %s )' % (NEG('a', 'b'), IMP('a', 'b')))], 'bicomi', '( -. %s <-> %s )' % (IMP('a', 'b'), NEG('a', 'b')))
b4 = w.s([b2, w.s([b3], 'rexbii', '( E. b e. ZZ -. %s <-> E. b e. ZZ %s )' % (IMP('a', 'b'), NEG('a', 'b')))], 'bitri', '( -. A. b e. ZZ %s <-> E. b e. ZZ %s )' % (IMP('a', 'b'), NEG('a', 'b')))
b5 = w.s([b1, w.s([b4], 'rexbii', '( E. a e. ZZ -. A. b e. ZZ %s <-> E. a e. ZZ E. b e. ZZ %s )' % (IMP('a', 'b'), NEG('a', 'b')))], 'bitri', '( -. %s <-> E. a e. ZZ E. b e. ZZ %s )' % (PERM, NEG('a', 'b')))
ex1 = w.s([nper, b5], 'sylib', '( %s -> E. a e. ZZ E. b e. ZZ %s )' % (A0, NEG('a', 'b')))
# rename a b -> s t
ias = w.s([], 'id', '( a = s -> a = s )'); c1, mid = w.wcongr(NEG('a', 'b'), {'a': 's'}, 'a = s', {'a': ias})
assert mid == NEG('s', 'b'), mid
ibt = w.s([], 'id', '( b = t -> b = t )'); c2, fin_ = w.wcongr(NEG('s', 'b'), {'b': 't'}, 'b = t', {'b': ibt})
assert fin_ == NEG('s', 't'), fin_
cbv = w.s([c1, c2], 'cbvrex2vw', '( E. a e. ZZ E. b e. ZZ %s <-> %s )' % (NEG('a', 'b'), EX))
w.qed([ex1, cbv], 'sylib', '( %s -> %s )' % (A0, EX)); run(w)

# ---- dchrgs0lem3
XU = XL('U'); GRA = GR('X', 'N', 'A'); AU = '( A x. U )'
A3 = '( ( %s /\\ A e. ZZ ) /\\ ( U e. ZZ /\\ %s /\\ N || ( A x. ( U - 1 ) ) ) /\\ %s =/= 1 )' % (HC, COP('U', 'N'), XU)
w = W('dchrgs0lem3', 'Lemma for dchrgs0 (Mathlib gaussSum_aux_of_mulShift): a unit U with A U congruent to A mod N and X ( U ) =/= 1 forces the shifted Gauss sum at A to vanish.')
h = w.s([], 'simp1', '( %s -> ( %s /\\ A e. ZZ ) )' % (A3, HC)); hc = w.s([h], 'simpld', '( %s -> %s )' % (A3, HC)); a = w.s([h], 'simprd', '( %s -> A e. ZZ )' % A3)
n = w.s([hc], 'simpld', '( %s -> N e. NN )' % A3); x = w.s([hc], 'simprd', '( %s -> X e. %s )' % (A3, DB('N')))
u3 = w.s([], 'simp2', '( %s -> ( U e. ZZ /\\ %s /\\ N || ( A x. ( U - 1 ) ) ) )' % (A3, COP('U', 'N'))); u = w.s([u3], 'simp1d', '( %s -> U e. ZZ )' % A3); cop = w.s([u3], 'simp2d', '( %s -> %s )' % (A3, COP('U', 'N'))); dv = w.s([u3], 'simp3d', '( %s -> N || ( A x. ( U - 1 ) ) )' % A3)
ne1 = w.s([], 'simp3', '( %s -> %s =/= 1 )' % (A3, XU))
m = w.s([hc, a, w.s([u, cop], 'jca', '( %s -> ( U e. ZZ /\\ %s ) )' % (A3, COP('U', 'N'))), w.inst('dchrgsmul')], 'syl3anc', '( %s -> ( %s x. %s ) = %s )' % (A3, XU, GR('X', 'N', AU), GRA))
acn = w.s([a], 'zcnd', '( %s -> A e. CC )' % A3); ucn = w.s([u], 'zcnd', '( %s -> U e. CC )' % A3)
alg = w.s([w.s([acn, ucn, w.s([], '1cnd', '( %s -> 1 e. CC )' % A3)], 'subdid', '( %s -> ( A x. ( U - 1 ) ) = ( %s - ( A x. 1 ) ) )' % (A3, AU)), w.s([w.s([acn], 'mulridd', '( %s -> ( A x. 1 ) = A )' % A3)], 'oveq2d', '( %s -> ( %s - ( A x. 1 ) ) = ( %s - A ) )' % (A3, AU, AU))], 'eqtrd', '( %s -> ( A x. ( U - 1 ) ) = ( %s - A ) )' % (A3, AU))
dv2 = w.s([dv, alg], 'breqtrd', '( %s -> N || ( %s - A ) )' % (A3, AU))
per = w.s([hc, w.s([w.s([a, u], 'zmulcld', '( %s -> %s e. ZZ )' % (A3, AU)), a], 'jca', '( %s -> ( %s e. ZZ /\\ A e. ZZ ) )' % (A3, AU)), dv2, w.inst('dchrgsper')], 'syl3anc', '( %s -> %s = %s )' % (A3, GR('X', 'N', AU), GRA))
key = w.s([w.s([per], 'oveq2d', '( %s -> ( %s x. %s ) = ( %s x. %s ) )' % (A3, XU, GR('X', 'N', AU), XU, GRA)), m], 'eqtr3d', '( %s -> ( %s x. %s ) = %s )' % (A3, XU, GRA, GRA))
g, z, d, l = dchyp(w)
xuc = w.s([g, z, d, l, x, u], 'dchrzrhcl', '( %s -> %s e. CC )' % (A3, XU))
# GR e. CC
Aa = '( %s /\\ a e. %s )' % (A3, F0)
az = w.s([w.s([], 'simpr', '( %s -> a e. %s )' % (Aa, F0)), w.inst('elfzoelz')], 'syl', '( %s -> a e. ZZ )' % Aa)
